#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
	int t;
	cin>>t;
	while(t--)
	{
	    int n;
	    cin>>n;
	    int m=3*n;
	    vector<long long>a(m);
	    for(long long &x:a)
	    {
	        cin>>x;
	    }
	    sort(a.begin(),a.end(),greater<long long>());
	    vector<long long> pref(m+1,0);
	    for(int i=0;i<m;i++)
	    {
	        pref[i+1]=pref[i]+a[i];
	    }
	    long long ans=0;
	    for(int k=0;k<=n;k++)
	    {
	        int low=0;
	        int high=n-k;
	        auto value=[&](int l)->long long{
	            int r=n-k-l;
	            int start4=k;
	            int end4=k+2*l;
	            int end3=end4+3*r;
	            long long part6=6LL*pref[k];
	            long long part4=4LL*(pref[end4]-pref[start4]);
	            long long part3=3LL*(pref[end3]-pref[end4]);
	            return part6+part4+part3;
	        };
	        while(low<high)
	        {
	            int mid=(low+high)/2;
	            if(value(mid)<=value(mid+1))
	            {
	                low=mid+1;
	            }
	            else
	            {
	                high=mid;
	            }
	        }
	        ans=max(ans,value(low));
	        
	            
	            
	        }
	        cout<<ans<<endl;
	    }
	    
	    
	}
